        from collections import defaultdict

        # dp[(s, p)] = set of products (<= limit) achievable, plus sentinel flag
        # We store: state -> (set of valid products, sentinel bool)
        # parity p = length of subsequence mod 2 (next position parity)
        dp = {}  # (s, p) -> [set_of_products, sentinel_bool]

        def add_state(d, s, p, prod):
            if prod <= limit:
                ent = d.get((s, p))
                if ent is None:
                    ent = [set(), False]
                    d[(s, p)] = ent
                ent[0].add(prod)
                # valid product exists; sentinel no longer needed for future? 
                # keep sentinel flag only if no valid product (handled in merge)
            else:
                ent = d.get((s, p))
                if ent is None:
                    d[(s, p)] = [set(), True]
                else:
                    if not ent[0]:
                        ent[1] = True
                    # if valid product exists, sentinel is redundant (valid dominates)

        for x in nums:
            new_dp = {}

            # start a new subsequence at x
            s = x
            p = 1
            prod = x
            if prod <= limit:
                ent = new_dp.get((s, p))
                if ent is None:
                    ent = [set(), False]
                    new_dp[(s, p)] = ent
                ent[0].add(prod)
            else:
                ent = new_dp.get((s, p))
                if ent is None:
                    new_dp[(s, p)] = [set(), True]
                else:
                    if not ent[0]:
                        ent[1] = True

            # extend existing states
            for (s, p), (prods, sentinel) in dp.items():
                # new sum
                ns = s + x if p == 0 else s - x
                np_ = 1 - p
                # from valid products
                for prod in prods:
                    new_prod = prod * x
                    if new_prod <= limit:
                        ent = new_dp.get((ns, np_))
                        if ent is None:
                            ent = [set(), False]
                            new_dp[(ns, np_)] = ent
                        ent[0].add(new_prod)
                    else:
                        ent = new_dp.get((ns, np_))
                        if ent is None:
                            new_dp[(ns, np_)] = [set(), True]
                        else:
                            if not ent[0]:
                                ent[1] = True
                # from sentinel (product > limit)
                if sentinel:
                    if x == 0:
                        # product becomes 0
                        ent = new_dp.get((ns, np_))
                        if ent is None:
                            ent = [set(), False]
                            new_dp[(ns, np_)] = ent
                        ent[0].add(0)
                    else:
                        # product stays > limit (x >= 1)
                        ent = new_dp.get((ns, np_))
                        if ent is None:
                            new_dp[(ns, np_)] = [set(), True]
                        else:
                            if not ent[0]:
                                ent[1] = True

            dp = new_dp

        best = -1
        for (s, p), (prods, sentinel) in dp.items():
            if s == k:
                for prod in prods:
                    if prod > best:
                        best = prod
        return best

