from math import sqrt

def main():
    input_data = sys.stdin.read().split()
    n = int(input_data[0])
    M = int(input_data[1])
    P = list(map(int, input_data[2:2 + n]))

    S = 0.0
    for p in P:
        S += 1.0 / p

    # Continuous optimum: x_i = A/P_i with A = sqrt(M/S)
    A = sqrt(M / S)

    def min_cost(T):
        """Minimal cost to buy exactly T units (exact integer arithmetic)."""
        if T <= 0:
            return 0
        Af = T / S
        q = [int(Af / p) for p in P]
        # q_i = floor(Af/P_i); Af may be slightly off due to float error
        s = sum(q)
        r = T - s
        if r > 0:
            # add 1 unit to the r products with smallest marginal cost
            m = [(2 * q[i] + 1) * P[i] for i in range(n)]
            order = sorted(range(n), key=lambda i: m[i])
            x = q[:]
            for i in order[:r]:
                x[i] += 1
            return sum(P[i] * x[i] * x[i] for i in range(n))
        elif r < 0:
            # remove -r units from products with largest removal marginal cost
            m = [(2 * q[i] - 1) * P[i] if q[i] > 0 else None for i in range(n)]
            cand = [(m[i], i) for i in range(n) if m[i] is not None]
            cand.sort(key=lambda t: -t[0])
            x = q[:]
            for k in range(-r):
                _, i = cand[k]
                x[i] -= 1
            return sum(P[i] * x[i] * x[i] for i in range(n))
        else:
            return sum(P[i] * q[i] * q[i] for i in range(n))

    def feasible(T):
        return min_cost(T) <= M

    # Binary search on T
    lo, hi = 0, 0
    # upper bound: sum x_i <= sqrt(N * M) (since sum x_i^2 <= M)
    hi = int(sqrt(n * M)) + 2
    # ensure feasibility at lo
    while feasible(hi):
        hi *= 2
    while not feasible(lo):
        lo -= 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    print(lo)

