from typing import List

class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + nums[i]
        C = [0] * (n + 1)
        for i in range(n):
            C[i + 1] = C[i] + cost[i]

        INF = 10 ** 30
        prev = [INF] * (n + 1)   # prev[i] = DP[i][m-1]
        prev[0] = 0
        ans = INF

        for m in range(1, n + 1):
            km = k * m
            cur = [INF] * (n + 1)
            dq = deque()  # lines (slope, intercept), slopes decreasing, front = best at query x
            for j in range(1, n + 1):
                x = P[j] + km
                b = prev[j - 1]          # intercept DP[j-1][m-1]
                if b < INF:
                    s = -C[j - 1]        # slope -C[j-1]
                    # remove back lines worse than the new line for all x >= current query x
                    while dq:
                        sb, bb = dq[-1]
                        if s * x + b < sb * x + bb:
                            dq.pop()
                        else:
                            break
                    dq.append((s, b))
                if not dq:
                    continue
                # pop front lines that are worse than the next line at x
                while len(dq) >= 2:
                    s0, b0 = dq[0]
                    s1, b1 = dq[1]
                    if s0 * x + b0 >= s1 * x + b1:
                        dq.popleft()
                    else:
                        break
                s0, b0 = dq[0]
                cur[j] = x * C[j] + s0 * x + b0

            if cur[n] < ans:
                ans = cur[n]
            prev = cur

        return ans

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        from collections import defaultdict

        # dp: (sum, parity) -> (best_valid_product, has_sentinel)
        # parity = length of subsequence mod 2 (next element position parity)
        dp = {}

        for x in nums:
            new_dp = {}
            # start a new subsequence starting at this element
            if x == 0:
                key = (0, 1)
                cur = new_dp.get(key)
                new_dp[key] = (0, False) if cur is None else (max(cur[0], 0) if cur[0] is not None else 0, cur[1])
            else:
                key = (x, 1)
                if x <= limit:
                    cur = new_dp.get(key)
                    if cur is None:
                        new_dp[key] = (x, False)
                    else:
                        new_dp[key] = (max(cur[0], x) if cur[0] is not None else x, cur[1])
                else:
                    key = (x, 1)
                    cur = new_dp.get(key)
                    if cur is None:
                        new_dp[key] = (None, True)
                    else:
                        new_dp[key] = (cur[0], True)

            # extend existing states
            for (s, p), (bv, sf) in dp.items():
                ns = s + x if p == 0 else s - x
                npar = 1 - p
                key = (ns, npar)
                cur = new_dp.get(key)
                cur_bv = cur[0] if cur else None
                cur_sf = cur[1] if cur else False

                if bv is not None:
                    prod = bv * x
                    if prod <= limit:
                        if cur_bv is None or prod > cur_bv:
                            cur_bv = prod
                    else:
                        cur_sf = True
                if sf:
                    if x == 0:
                        if cur_bv is None or 0 > cur_bv:
                            cur_bv = 0
                    else:
                        cur_sf = True

                if cur_bv is not None:
                    new_dp[key] = (cur_bv, cur_sf)
                else:
                    new_dp[key] = (None, True) if cur_sf else (None, False)

            # cleanup: remove states with neither valid product nor sentinel
            new_dp = {key: val for key, val in new_dp.items() if val[0] is not None or val[1]}
            dp = new_dp

        # answer: max valid product at sum k
        best = -1
        for (s, p), (bv, sf) in dp.items():
            if s == k and bv is not None:
                if bv > best:
                    best = bv
        return best
